(function(){document.querySelectorAll(".vl-home-gif-link").forEach(e=>{const t=e.querySelector("img[data-reveal-src]");if(!t)return;const n=new Image;n.srcset=t.dataset.revealSrcset,n.src=t.dataset.revealSrc;function s(){const n=e.matches(":hover, :focus");t.srcset=n?t.dataset.revealSrcset:t.dataset.idleSrcset,t.src=n?t.dataset.revealSrc:t.dataset.idleSrc}["pointerenter","pointerleave","focus","blur"].forEach(t=>e.addEventListener(t,s))})})()